// GENERATED by scripts/build-io.mjs from src/ - edit the source, not this file.
// Client for Weni's WebChat ("wwc") socket protocol.
//
// This is NOT reverse-engineered guesswork: the transport is open source and
// documented at https://github.com/weni-ai/weni-webchat-socket, and this file
// mirrors the validated implementation in the faststore-agentic-base project
// (src/utils/agentSocket.ts + useAgentChat.ts), trimmed to a dependency-free
// version for a plain console-injected script (no React context, no VTEX
// GraphQL cart resolution).
//
// Wire summary:
//   connect wss://<socketUrl>/ws
//   -> {type:"register", from, callback, trigger?, token?}   (mandatory first frame)
//   <- {type:"ready_for_message", data:{history:[...]}}       (registration ack + thread)
//   <- {type:"forbidden", warning}                             (Origin not allowlisted - do not retry)
//   <- {type:"ping"}  -> client replies {type:"pong"}          (server-initiated keepalive)
//   -> {type:"message", message:{type:"text", text}}
//   -> {type:"message", message:{type:"image|video|audio|file", media:"data:<mime>;base64,…", caption?}}
//   <- {type:"ack", message:{... media_url}}                   (the socket's S3 copy of what we just sent)
//   <- {type:"typing_start"} / {type:"typing_stop"}
//   <- {type:"message", message:{...}}                         (a complete reply)
//   <- {type:"stream_start", id} -> {v, seq} deltas (no "type") -> {type:"stream_end", id, content}
//   -> {type:"set_custom_field", data:{key, value}}            (writes one contact field)
//   -> {type:"message_with_fields", message:{…}, data:{…}}     (a message that carries fields)
//   -> {type:"get_history", params:{limit, page}}               (paging further back only)

const DEFAULT_SOCKET_URL = 'wss://websocket.weni.ai/ws';
const DEFAULT_FLOWS_ORIGIN = 'https://flows.weni.ai';
const RECONNECT_BASE_MS = 800;
const RECONNECT_MAX_MS = 15_000;
const MAX_RECONNECT_ATTEMPTS = 8;

/** The media message types the socket accepts from a client. */
export type MediaKind = 'image' | 'video' | 'audio' | 'file';

export type SocketStatus =
  | 'idle'
  | 'connecting'
  | 'registering'
  | 'ready'
  | 'reconnecting'
  | 'forbidden'
  | 'failed';

export interface WireProductItem {
  product_retailer_id?: string;
  /** The catalog_message spelling of the same field. */
  retailer_id?: string;
  name?: string;
  price?: string;
  sale_price?: string;
  currency?: string;
  image?: string;
  description?: string;
  seller_id?: string;
  product_url?: string;
}

export interface WireMessageBody {
  type?: string;
  text?: string;
  /** Outgoing only: a `data:` URI the socket decodes, stores and turns into `media_url`. */
  media?: string;
  media_url?: string;
  caption?: string;
  quick_replies?: string[];
  list_message?: {
    button_text?: string;
    list_items?: Array<{ uuid?: string; title?: string; description?: string }>;
  };
  interactive?: {
    header?: { text?: string };
    action?: {
      product_items?: WireProductItem[];
      sections?: Array<{ title?: string; product_items?: WireProductItem[] }>;
    };
  };
  order?: { product_items?: WireProductItem[] };
  /**
   * The WebChat catalog, which is what `WeniWebChatCatalog` in the agent
   * toolkit emits (weni/broadcasts/messages.py). Note the key is `retailer_id`
   * here, not `product_retailer_id` as under `interactive`.
   */
  catalog_message?: {
    action_button_text?: string;
    products?: Array<{
      product?: string;
      product_retailer_info?: WireProductItem[];
    }>;
  };
}

export interface AgentSocketFrame {
  type?: string;
  warning?: string;
  error?: string;
  message?: WireMessageBody;
  id?: string;
  content?: string;
  v?: string;
  seq?: number;
  data?: { history?: WireHistoryEntry[]; [key: string]: unknown };
  [key: string]: unknown;
}

export interface WireHistoryEntry {
  // NOTE (measured, not documented): the server's `in` is the AGENT and its
  // `out` is the SHOPPER - inverted relative to how this file names sides.
  direction?: 'in' | 'out' | string;
  timestamp?: string | number;
  message?: WireMessageBody;
}

function isStreamDelta(frame: AgentSocketFrame): frame is AgentSocketFrame & { v: string } {
  return frame.type === undefined && typeof frame.v === 'string';
}

export interface WwcClientOptions {
  from: string;
  channelUuid: string;
  socketUrl?: string;
  flowsOrigin?: string;
  trigger?: string;
  onFrame: (frame: AgentSocketFrame) => void;
  onStatus: (status: SocketStatus) => void;
  onForbidden: (warning: string) => void;
}

export class WwcClient {
  private ws: WebSocket | null = null;
  private opts: WwcClientOptions;
  private attempts = 0;
  private closedByUs = false;
  private disposed = false;
  private registered = false;
  private reconnectTimer: number | undefined;

  constructor(opts: WwcClientOptions) {
    this.opts = opts;
  }

  private get callbackUrl(): string {
    const origin = this.opts.flowsOrigin || DEFAULT_FLOWS_ORIGIN;
    return `${origin}/c/wwc/${this.opts.channelUuid}/receive`;
  }

  private emitStatus(status: SocketStatus) {
    if (!this.disposed) this.opts.onStatus(status);
  }

  private emitFrame(frame: AgentSocketFrame) {
    if (!this.disposed) this.opts.onFrame(frame);
  }

  connect() {
    if (this.disposed || this.ws || !this.opts.from || !this.opts.channelUuid) return;

    this.closedByUs = false;
    this.emitStatus(this.attempts === 0 ? 'connecting' : 'reconnecting');

    let socket: WebSocket;
    try {
      socket = new WebSocket(this.opts.socketUrl || DEFAULT_SOCKET_URL);
    } catch (cause) {
      this.closedByUs = true;
      this.emitStatus('failed');
      this.opts.onForbidden(`invalid socket URL: ${cause instanceof Error ? cause.message : cause}`);
      return;
    }

    this.ws = socket;

    socket.addEventListener('open', () => {
      this.attempts = 0;
      this.registered = false;
      this.emitStatus('registering');
      this.send({
        type: 'register',
        from: this.opts.from,
        callback: this.callbackUrl,
        ...(this.opts.trigger ? { trigger: this.opts.trigger } : {}),
      });
    });

    socket.addEventListener('message', (evt) => this.handle(evt));

    // No `error` listener on purpose: the browser's WebSocket error event
    // carries no useful info and is always followed by `close`, which drives
    // the reconnect on its own.
    socket.addEventListener('close', () => {
      this.ws = null;
      this.registered = false;
      if (this.closedByUs) {
        this.emitStatus('idle');
        return;
      }
      this.scheduleReconnect();
    });
  }

  private handle(evt: MessageEvent) {
    if (typeof evt.data !== 'string') return;
    let frame: AgentSocketFrame;
    try {
      frame = JSON.parse(evt.data);
    } catch {
      return;
    }

    if (frame.type === 'forbidden') {
      // Origin not on the channel's domain allowlist - retrying will fail
      // again forever, so this is a dead end, not a blip.
      this.closedByUs = true;
      this.emitStatus('forbidden');
      this.opts.onForbidden(frame.warning ?? 'domain not allowed, forbidden connection');
      this.ws?.close();
      return;
    }

    // The first non-rejection frame means the register landed - there is no
    // dedicated "registered" frame beyond that, and this must run BEFORE the
    // ping handler below (a ping arriving before the real ack must still flip
    // this) - see the timing note in the faststore-agentic-base source.
    if (!this.registered) {
      this.registered = true;
      this.emitStatus('ready');
    }

    // Keepalive: the SERVER sends ping, we answer pong. Not forwarded.
    if (frame.type === 'ping') {
      this.send({ type: 'pong' });
      return;
    }

    this.emitFrame(frame);
  }

  requestHistory(limit = 50, page = 1) {
    this.send({ type: 'get_history', params: { limit, page } });
  }

  /**
   * `fields` turns the frame into `message_with_fields`, which is how the
   * official widget delivers contact fields collected before the contact
   * existed: everything in `data` is written onto the contact along with the
   * message (pkg/websocket/helper.go).
   */
  sendText(text: string, fields?: Record<string, string>): boolean {
    return this.sendMessageFrame({ type: 'text', text }, fields);
  }

  sendQuickReply(text: string): boolean {
    return this.sendText(text);
  }

  /**
   * Attachments go up as a `data:` URI in `media`: the socket decodes it,
   * stores the file and forwards the hosted `media_url` to Flows, then echoes
   * an `ack` frame carrying that URL back to us. There is no separate upload
   * endpoint - see pkg/websocket/helper.go in weni-ai/weni-webchat-socket.
   *
   * That helper reads the file extension from the MIME type between `/` and
   * `;`, so the data URI must keep its standard `data:<type>/<subtype>;base64,`
   * prefix intact.
   */
  sendMedia(kind: MediaKind, dataUri: string, caption?: string, fields?: Record<string, string>): boolean {
    return this.sendMessageFrame({ type: kind, media: dataUri, ...(caption ? { caption } : {}) }, fields);
  }

  private sendMessageFrame(message: WireMessageBody, fields?: Record<string, string>): boolean {
    const hasFields = Boolean(fields && Object.keys(fields).length);
    return this.send({
      type: hasFields ? 'message_with_fields' : 'message',
      message,
      ...(hasFields ? { data: fields } : {}),
    });
  }

  /**
   * Writes one field onto the contact in CX Platform. The socket forwards it to
   * Flows as `PATCH /api/v2/internals/update_contacts_fields` for urn
   * `ext:<from>`, so it only lands once that contact exists - which is why
   * fields resolved before the first message ride along with it instead.
   */
  setCustomField(key: string, value: string): boolean {
    return this.send({ type: 'set_custom_field', data: { key, value } });
  }

  private send(payload: unknown): boolean {
    if (this.ws?.readyState !== WebSocket.OPEN) return false;
    this.ws.send(JSON.stringify(payload));
    return true;
  }

  private scheduleReconnect() {
    this.attempts += 1;
    if (this.attempts > MAX_RECONNECT_ATTEMPTS) {
      this.emitStatus('failed');
      return;
    }
    const backoff = Math.min(RECONNECT_BASE_MS * 2 ** (this.attempts - 1), RECONNECT_MAX_MS);
    const delay = backoff * (0.7 + Math.random() * 0.6);
    this.emitStatus('reconnecting');
    window.clearTimeout(this.reconnectTimer);
    this.reconnectTimer = window.setTimeout(() => this.connect(), delay);
  }

  close() {
    this.closedByUs = true;
    this.disposed = true;
    window.clearTimeout(this.reconnectTimer);
    this.ws?.close();
    this.ws = null;
    this.registered = false;
  }
}

export { isStreamDelta };
